options.customCss:
:root {
	--font-family: 'Inter', 'Poppins', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;
	--font-size-body: 14px;
	--font-size-label: 14px;
	--font-size-test-notice: 12px;
	--font-size-input: 15px;
	--font-size-header: 24px;
	--font-size-paragraph: 14px;
	--font-size-link: 13px;
	--font-size-error: 12px;
	--font-size-html-h1: 32px;
	--font-size-html-h2: 24px;
	--font-size-html-h3: 18px;
	--font-size-html-h4: 16px;
	--font-size-html-h5: 14px;
	--font-size-html-h6: 12px;
	--font-size-subheader: 15px;

	/* Colors - Modern Blue/Purple Theme */
	--color-background: #f4f6fb;
	--color-test-notice-text: #d97706;
	--color-test-notice-bg: #fffbeb;
	--color-test-notice-border: #fde68a;
	--color-card-bg: #ffffff;
	--color-card-border: #e5e7eb;
	--color-card-shadow: rgba(79, 70, 229, 0.08);
	--color-link: #6366f1;
	--color-header: #1f2937;
	--color-label: #374151;
	--color-input-border: #d1d5db;
	--color-input-text: #374151;
	--color-focus-border: #6366f1;
	--color-submit-btn-bg: #6366f1;
	--color-submit-btn-text: #ffffff;
	--color-error: #ef4444;
	--color-required: #ef4444;
	--color-clear-button-bg: #9ca3af;
	--color-html-text: #4b5563;
	--color-html-link: #6366f1;
	--color-header-subtext: #6b7280;

	/* Border Radii - Softer, Modern */
	--border-radius-card: 16px;
	--border-radius-input: 10px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 16px;

	/* Spacing - More Breathing Room */
	--padding-container-top: 40px;
	--padding-card: 32px;
	--padding-test-notice-vertical: 14px;
	--padding-test-notice-horizontal: 24px;
	--margin-bottom-card: 20px;
	--padding-form-input: 14px;
	--card-padding: 32px;
	--card-margin-bottom: 20px;

	/* Dimensions */
	--container-width: 480px;
	--submit-btn-height: 52px;
	--checkbox-size: 20px;

	/* Others - Stronger Shadow for Depth */
	--box-shadow-card: 0px 8px 30px 0px var(--color-card-shadow);
	--opacity-placeholder: 0.6;
}
